import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import './in'
// Public pages
import Landing      from "./pages/Landing";
import Login        from "./pages/Login";
import Registration from "./pages/Registration";
import NotFound     from "./pages/NotFound";

// Student pages
import StudentLayout       from "./pages/StudentLayout";
import StudentSearch       from "./pages/StudentSearch";
import StudentApplications from "./pages/student/StudentApplications";
import StudentProfile      from "./pages/StudentProfile";
//company pages
import CompanyDashboard from"./pages/CompanyDashboard";
import CompanyCandidates from "./pages/CompanyCandidates";

import CompanyOffers from "./pages/CompanyOffers";
import CompanyProfile from "./pages/CompanyProfile"
export default function App() {
  return (
    <BrowserRouter>
      <Routes>

        {/* Public */}
        <Route path="/"         element={<Landing />} />
        <Route path="/login"    element={<Login />} />
        <Route path="/register" element={<Registration />} />

        {/* Student */}
        <Route path="/student/dashboard"     element={<StudentLayout />} />
        <Route path="/student/search"        element={<StudentSearch />} />
        <Route path="/student/applications"  element={<StudentApplications />} />
        <Route path="/student/profile"       element={<StudentProfile />} />
        {/*company*/}
        <Route path="/company/dashboard"     element={<CompanyDashboard />} />
        <Route path="/student/condidates"     element={<CompanyCandidates />} />
        <Route path="/student/offers"     element={<CompanyOffers />} />
        <Route path="/student/profile"     element={<CompanyProfile />} />
        
        {/* Redirect */}
        <Route path="/student" element={<Navigate to="/student/dashboard" replace />} />

        {/* 404 */}
        <Route path="*" element={<NotFound />} />

      </Routes>
    </BrowserRouter>
  );
}
